#!/usr/bin/env python3

###
# Compares every compiled unit with the target object extracted by dtk,
# section by section and function by function.
#
# Usage:
#   python3 configure.py && ninja      # generates objdiff.json and the objects
#   python3 tools/check_units.py [--json] [--verbose] [--objdiff objdiff.json]
#
# The unit list and the Matching flags are read from objdiff.json, which
# configure.py writes ("complete" is the Matching flag of configure.py;
# "target_path" is the object extracted by `dtk dol split`, "base_path" the
# object compiled from src/). Autogenerated units are not listed there.
#
# For every allocated section of the target object, the compiled object must
# have a section with the same name, the same size, the same relocations
# (offset and type, and the same symbol name when both sides name a global
# symbol) and the same bytes once the fields patched by relocations are masked
# on both sides. BSS sections are compared by size only. Functions are also
# compared one by one (same name, size and masked bytes) to point at the first
# differing function.
#
# Per unit status:
#   match     the compiled object is equivalent to the target object
#   mismatch  first difference given as section, symbol+offset and reason
#   missing   no compiled object (no source configured, or not built:
#             NonMatching units are not built by the default target, build
#             them with `ninja <base_path>` or `ninja all_source`)
#
# Exit code: 1 when a unit marked Matching is not a match (error), else 0.
# A unit marked NonMatching that matches is reported as a hint.
#
# Python standard library only. Released under CC0 1.0.
###

import argparse
import json
import os
import struct
import sys
from typing import Dict, List, Optional, Tuple

SHT_SYMTAB = 2
SHT_RELA = 4
SHT_NOBITS = 8
SHT_REL = 9
SHF_ALLOC = 0x2
SHF_EXECINSTR = 0x4
STT_FUNC = 2
STT_SECTION = 3
STB_LOCAL = 0

# PowerPC relocation types (System V ABI PowerPC supplement and EABI):
# (number of bytes patched, starting offset alignment, bit mask of the field)
R_PPC = {
    1: ("ADDR32", 4, 0, 0xFFFFFFFF),
    2: ("ADDR24", 4, 0, 0x03FFFFFC),
    3: ("ADDR16", 2, 0, 0xFFFF),
    4: ("ADDR16_LO", 2, 0, 0xFFFF),
    5: ("ADDR16_HI", 2, 0, 0xFFFF),
    6: ("ADDR16_HA", 2, 0, 0xFFFF),
    7: ("ADDR14", 4, 0, 0x0000FFFC),
    8: ("ADDR14_BRTAKEN", 4, 0, 0x0000FFFC),
    9: ("ADDR14_BRNTAKEN", 4, 0, 0x0000FFFC),
    10: ("REL24", 4, 0, 0x03FFFFFC),
    11: ("REL14", 4, 0, 0x0000FFFC),
    12: ("REL14_BRTAKEN", 4, 0, 0x0000FFFC),
    13: ("REL14_BRNTAKEN", 4, 0, 0x0000FFFC),
    26: ("REL32", 4, 0, 0xFFFFFFFF),
    109: ("EMB_SDA21", 4, 0, 0x001FFFFF),
}


class Section:
    def __init__(self, index, name, sh_type, flags, offset, size, link, info, align, data):
        self.index = index
        self.name = name
        self.type = sh_type
        self.flags = flags
        self.offset = offset
        self.size = size
        self.link = link
        self.info = info
        self.align = align
        self.data = data
        self.relocs = []  # (offset, type, symbol index, addend)


class Symbol:
    def __init__(self, name, value, size, info, shndx):
        self.name = name
        self.value = value
        self.size = size
        self.type = info & 0xF
        self.bind = info >> 4
        self.shndx = shndx


class Elf:
    """Minimal ELF32 big-endian relocatable object reader."""

    def __init__(self, path: str):
        with open(path, "rb") as f:
            data = f.read()
        if data[:4] != b"\x7fELF" or data[4] != 1 or data[5] != 2:
            raise ValueError(f"{path}: not an ELF32 big-endian file")
        (e_shoff,) = struct.unpack_from(">I", data, 0x20)
        e_shentsize, e_shnum, e_shstrndx = struct.unpack_from(">HHH", data, 0x2E)
        raw = []
        for i in range(e_shnum):
            raw.append(struct.unpack_from(">IIIIIIIIII", data, e_shoff + i * e_shentsize))
        shstr = raw[e_shstrndx]
        shstrtab = data[shstr[4] : shstr[4] + shstr[5]]

        def cstr(table, off):
            end = table.index(b"\0", off)
            return table[off:end].decode("latin-1")

        self.sections: List[Section] = []
        for i, (name, sh_type, flags, _addr, off, size, link, info, align, _ent) in enumerate(raw):
            content = b"" if sh_type == SHT_NOBITS else data[off : off + size]
            self.sections.append(
                Section(i, cstr(shstrtab, name), sh_type, flags, off, size, link, info, align, content)
            )

        self.symbols: List[Symbol] = []
        for sec in self.sections:
            if sec.type != SHT_SYMTAB:
                continue
            strtab = self.sections[sec.link].data
            for j in range(sec.size // 16):
                st_name, value, size, info, _other, shndx = struct.unpack_from(">IIIBBH", sec.data, j * 16)
                self.symbols.append(Symbol(cstr(strtab, st_name), value, size, info, shndx))
            break

        for sec in self.sections:
            if sec.type not in (SHT_RELA, SHT_REL):
                continue
            target = self.sections[sec.info]
            entsize = 12 if sec.type == SHT_RELA else 8
            for j in range(sec.size // entsize):
                if sec.type == SHT_RELA:
                    r_off, r_info, r_add = struct.unpack_from(">IIi", sec.data, j * entsize)
                else:
                    r_off, r_info = struct.unpack_from(">II", sec.data, j * entsize)
                    r_add = 0
                target.relocs.append((r_off, r_info & 0xFF, r_info >> 8, r_add))

    def alloc_sections(self) -> List[Section]:
        return [s for s in self.sections if s.flags & SHF_ALLOC and s.size > 0]

    def symbols_in(self, sec: Section) -> List[Symbol]:
        return sorted(
            (s for s in self.symbols if s.shndx == sec.index and s.type != STT_SECTION and s.name),
            key=lambda s: (s.value, -s.size),
        )


def reloc_mask(sec: Section) -> bytearray:
    """Byte mask of a section: 0 bits where a relocation patches the field."""
    mask = bytearray(b"\xff" * sec.size)
    for r_off, r_type, _sym, _add in sec.relocs:
        nbytes, _start, field = R_PPC.get(r_type, ("?", 4, 0, 0xFFFFFFFF))[1:]
        start = r_off
        if nbytes == 4:
            start = r_off & ~3
        for k in range(nbytes):
            pos = start + k
            if pos < len(mask):
                shift = 8 * (nbytes - 1 - k)
                mask[pos] &= ~((field >> shift) & 0xFF) & 0xFF
    return mask


def reloc_key(r_off: int, r_type: int) -> Tuple[int, int]:
    return (r_off & ~3, r_type)


def sym_label(syms: List[Symbol], off: int) -> str:
    best = None
    for s in syms:
        if s.value <= off and (off < s.value + max(s.size, 1) or (s.size == 0 and best is None)):
            if best is None or s.value >= best.value:
                best = s
    if best is None:
        return f"0x{off:X}"
    return f"{best.name}+0x{off - best.value:X}"


def reloc_name(elf: Elf, sym_index: int) -> Tuple[str, bool]:
    s = elf.symbols[sym_index] if sym_index < len(elf.symbols) else None
    if s is None:
        return ("?", False)
    named_global = s.bind != STB_LOCAL and s.type != STT_SECTION
    return (s.name, named_global)


def compare_relocs(t_elf, t_sec, b_elf, b_sec, start, end) -> Optional[Tuple[int, str]]:
    """First relocation difference in [start, end), as (offset, reason)."""
    t = {}
    for r in t_sec.relocs:
        if start <= r[0] < end:
            t[reloc_key(r[0], r[1])] = r
    b = {}
    for r in b_sec.relocs:
        if start <= r[0] < end:
            b[reloc_key(r[0], r[1])] = r
    for key in sorted(set(t) | set(b)):
        if key not in b:
            return (key[0], f"relocation {R_PPC.get(key[1], (str(key[1]),))[0]} only in target")
        if key not in t:
            return (key[0], f"relocation {R_PPC.get(key[1], (str(key[1]),))[0]} only in compiled")
        t_name, t_glob = reloc_name(t_elf, t[key][2])
        b_name, b_glob = reloc_name(b_elf, b[key][2])
        if t_name == b_name and t[key][3] != b[key][3]:
            return (key[0], f"relocation addend {t_name}+0x{t[key][3]:X} vs +0x{b[key][3]:X}")
        if t_glob and b_glob and t_name != b_name:
            return (key[0], f"relocation target {t_name} vs {b_name}")
    return None


def first_byte_diff(t_data, b_data, mask, start, end) -> Optional[int]:
    for i in range(start, end):
        if (t_data[i] & mask[i]) != (b_data[i] & mask[i]):
            return i
    return None


def compare_section(t_elf, t_sec, b_elf, b_sec) -> Optional[Tuple[int, str]]:
    if t_sec.type == SHT_NOBITS or b_sec.type == SHT_NOBITS:
        if t_sec.type != b_sec.type:
            return (0, "section type differs (bss vs data)")
        if t_sec.size != b_sec.size:
            return (min(t_sec.size, b_sec.size), f"size 0x{t_sec.size:X} vs 0x{b_sec.size:X}")
        return None
    size = min(t_sec.size, b_sec.size)
    mask = reloc_mask(t_sec)
    b_mask = reloc_mask(b_sec)
    for i in range(size):
        mask[i] &= b_mask[i]
    issues = []
    diff = first_byte_diff(t_sec.data, b_sec.data, mask, 0, size)
    if diff is not None:
        issues.append((diff, "bytes differ"))
    rel = compare_relocs(t_elf, t_sec, b_elf, b_sec, 0, max(t_sec.size, b_sec.size))
    if rel is not None:
        issues.append(rel)
    if t_sec.size != b_sec.size:
        issues.append((size, f"size 0x{t_sec.size:X} vs 0x{b_sec.size:X}"))
    if not issues:
        return None
    return min(issues, key=lambda x: x[0])


def compare_functions(t_elf, t_sec, b_elf) -> Tuple[int, int, Optional[dict]]:
    """Returns (matched, total, first differing function info)."""
    b_by_name = {}
    for s in b_elf.symbols:
        if s.type == STT_FUNC and s.shndx < len(b_elf.sections):
            b_by_name.setdefault(s.name, s)
    t_mask = reloc_mask(t_sec)
    matched = 0
    total = 0
    first = None
    for s in t_elf.symbols_in(t_sec):
        if s.type != STT_FUNC:
            continue
        total += 1
        b = b_by_name.get(s.name)
        reason = None
        off = 0
        if b is None:
            reason = "not found in compiled object"
        else:
            b_sec = b_elf.sections[b.shndx]
            if b.size != s.size:
                reason = f"size 0x{s.size:X} vs 0x{b.size:X}"
                off = min(s.size, b.size)
            b_mask = reloc_mask(b_sec)
            n = min(s.size, b.size)
            for i in range(n):
                tm = t_mask[s.value + i] & b_mask[b.value + i]
                if (t_sec.data[s.value + i] & tm) != (b_sec.data[b.value + i] & tm):
                    reason = "bytes differ"
                    off = i
                    break
            if reason is None or reason.startswith("size"):
                # Relocations, compared relative to the function start.
                t_rel = {reloc_key(r[0] - s.value, r[1]): r for r in t_sec.relocs if s.value <= r[0] < s.value + s.size}
                b_rel = {reloc_key(r[0] - b.value, r[1]): r for r in b_sec.relocs if b.value <= r[0] < b.value + b.size}
                if set(t_rel) != set(b_rel):
                    k = min(set(t_rel) ^ set(b_rel))
                    if reason is None or k[0] < off:
                        reason, off = "relocations differ", k[0]
        if reason is None:
            matched += 1
        elif first is None:
            first = {"function": s.name, "offset": off, "reason": reason}
    return matched, total, first


def compare_unit(target_path: str, base_path: str) -> dict:
    t_elf = Elf(target_path)
    b_elf = Elf(base_path)
    b_secs: Dict[str, Section] = {}
    for s in b_elf.alloc_sections():
        b_secs.setdefault(s.name, s)
    result = {"status": "match", "sections": {}, "functions_matched": 0, "functions_total": 0}
    first_issue = None
    t_names = set()
    for t_sec in t_elf.alloc_sections():
        t_names.add(t_sec.name)
        b_sec = b_secs.get(t_sec.name)
        if b_sec is None:
            issue = {"section": t_sec.name, "offset": 0, "symbol": sym_label(t_elf.symbols_in(t_sec), 0),
                     "reason": "section missing in compiled object"}
        else:
            diff = compare_section(t_elf, t_sec, b_elf, b_sec)
            issue = None
            if diff is not None:
                issue = {"section": t_sec.name, "offset": diff[0],
                         "symbol": sym_label(t_elf.symbols_in(t_sec), diff[0]), "reason": diff[1]}
        if t_sec.flags & SHF_EXECINSTR and t_sec.type != SHT_NOBITS:
            m, t, first_fn = compare_functions(t_elf, t_sec, b_elf)
            result["functions_matched"] += m
            result["functions_total"] += t
            if first_fn is None and issue is not None and m == t > 0:
                issue["reason"] += "; every function matches on its own: function order differs"
            if first_fn is not None and issue is not None:
                issue["function"] = first_fn
            elif first_fn is not None:
                issue = {"section": t_sec.name, "offset": 0, "symbol": first_fn["function"],
                         "reason": "function differs", "function": first_fn}
        result["sections"][t_sec.name] = "match" if issue is None else "mismatch"
        if issue is not None and first_issue is None:
            first_issue = issue
    for name, b_sec in b_secs.items():
        if name not in t_names:
            result["sections"][name] = "mismatch"
            if first_issue is None:
                first_issue = {"section": name, "offset": 0, "symbol": "",
                               "reason": f"extra section in compiled object (0x{b_sec.size:X} bytes)"}
    if first_issue is not None:
        result["status"] = "mismatch"
        result["first_difference"] = first_issue
    return result


def main():
    parser = argparse.ArgumentParser(description="Compare compiled units with dtk target objects.")
    parser.add_argument("--objdiff", default="objdiff.json", help="objdiff.json written by configure.py")
    parser.add_argument("--json", action="store_true", help="print the results as JSON")
    parser.add_argument("--verbose", action="store_true", help="also list matching units")
    args = parser.parse_args()

    root = os.path.abspath(os.path.join(os.path.dirname(os.path.realpath(__file__)), ".."))
    objdiff_path = os.path.join(root, args.objdiff) if not os.path.isabs(args.objdiff) else args.objdiff
    if not os.path.exists(objdiff_path):
        sys.exit(f"{objdiff_path} not found: run `python3 configure.py` first")
    configure_py = os.path.join(root, "configure.py")
    if os.path.getmtime(configure_py) > os.path.getmtime(objdiff_path):
        print("warning: configure.py is newer than objdiff.json, run `python3 configure.py`", file=sys.stderr)
    with open(objdiff_path, encoding="utf-8") as f:
        units = json.load(f)["units"]

    results = []
    for unit in units:
        name = unit["name"]
        matching = bool(unit.get("complete", False))
        target = os.path.join(root, unit["target_path"])
        entry = {"unit": name, "matching_flag": matching, "target": unit["target_path"]}
        base_rel = unit.get("base_path")
        if base_rel:
            entry["base"] = base_rel
        if not os.path.exists(target):
            entry["status"] = "missing"
            entry["detail"] = "target object not found (run ninja to split the DOL)"
        elif not base_rel:
            entry["status"] = "missing"
            entry["detail"] = "no source configured in configure.py"
        elif not os.path.exists(os.path.join(root, base_rel)):
            entry["status"] = "missing"
            entry["detail"] = f"compiled object not built (ninja {base_rel})"
        else:
            try:
                entry.update(compare_unit(target, os.path.join(root, base_rel)))
            except (ValueError, OSError, struct.error) as e:
                entry["status"] = "mismatch"
                entry["detail"] = f"cannot compare: {e}"
        if matching and entry["status"] != "match":
            entry["level"] = "error"
        elif not matching and entry["status"] == "match":
            entry["level"] = "hint"
        results.append(entry)

    errors = [r for r in results if r.get("level") == "error"]
    hints = [r for r in results if r.get("level") == "hint"]

    if args.json:
        print(json.dumps({"units": results, "errors": len(errors), "hints": len(hints)}, indent=2))
    else:
        for r in results:
            if r["status"] == "match" and not args.verbose and r.get("level") != "hint":
                continue
            flag = "Matching" if r["matching_flag"] else "NonMatching"
            line = f"{r['status']:8} {r['unit']} [{flag}]"
            if "functions_total" in r and r["functions_total"]:
                line += f" functions {r['functions_matched']}/{r['functions_total']}"
            fd = r.get("first_difference")
            if fd:
                line += f"\n         first difference: {fd['section']} {fd['symbol']} ({fd['reason']})"
                fn = fd.get("function")
                if fn:
                    line += f"\n         first differing function: {fn['function']}+0x{fn['offset']:X} ({fn['reason']})"
            if r.get("detail"):
                line += f"\n         {r['detail']}"
            if r.get("level") == "error":
                line = "ERROR " + line
            elif r.get("level") == "hint":
                line = "HINT  " + line + "\n         marked NonMatching but identical: can be set to Matching"
            else:
                line = "      " + line
            print(line)
        counts = {}
        for r in results:
            counts[r["status"]] = counts.get(r["status"], 0) + 1
        summary = ", ".join(f"{k} {v}" for k, v in sorted(counts.items()))
        print(f"{len(results)} units: {summary}; {len(errors)} error(s), {len(hints)} hint(s)")
    sys.exit(1 if errors else 0)


if __name__ == "__main__":
    main()
